#include <cmath>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

int main()
{
    std::string line{};
    while (std::cout << "> " && std::getline(std::cin, line))
    {
        std::vector<double> stack{};
        std::istringstream words{ line };
        std::string token{};
        bool ok{ true };
        while (words >> token)
        {
            if (token == "+")
            {
                if (stack.size() < 2) { std::cout << "Error: not enough operands\n"; ok = false; break; }
                const double b{ stack.back() }; stack.pop_back();
                const double a{ stack.back() }; stack.pop_back();
                stack.push_back(a + b);
            }
            // TODO: - * / ^ sqrt dup swap
            else
            {
                stack.push_back(std::stod(token));      // a number
            }
        }
        if (ok && stack.size() == 1) std::cout << stack.back() << '\n';
    }
    return 0;
}

